// Load the Dr. Wei character spec from the mounted accounts volume
// and extract the system_prompt field. Single source of truth — if the
// spec file changes, this workflow picks it up on the next run.
const fs = require('fs');
const specPath = '/data/accounts/dr-wei/character-spec.json';
const spec = JSON.parse(fs.readFileSync(specPath, 'utf8'));

if (!spec.system_prompt) {
  throw new Error('system_prompt field missing from character-spec.json');
}

// V1 test brief: Script #1 from the hook-library sequence.
// Bridge pillar, H1 hook, B1 body, Phase 1 Day 1, no CTA.
//
// CRITICAL: we ask Claude to wrap the exact voiceover text in
// <voiceover>...</voiceover> tags so the downstream HeyGen node
// can extract only the spoken text (no hooks, no caption, no hashtags).
const userBrief = [
  'Generate a TikTok script for Dr. Wei following the exact protocol below.',
  '',
  'PHASE: 1 (Day 1)',
  'PLATFORM: TikTok (30–45 seconds, ~100–130 words)',
  'PILLAR: bridge',
  'HOOK TEMPLATE: H1 — Specific Pain Hook',
  'BODY STRUCTURE: B1 — Bridge (TCM concept → Western equivalent → implication)',
  'TOPIC: Why you wake at exactly 3am — the TCM liver clock (1–3am = Liver time, 肝 Gān) mapped to modern cortisol dysregulation research.',
  'CTA ALLOWED: no (pre-Day 60 trust-building phase)',
  'AFFILIATE CONTEXT: none — no product mentions',
  '',
  'OUTPUT FORMAT (markdown, in this exact order):',
  '1. ## Hook Variants — five hook variants, one sentence each.',
  '2. ## Full Script — the ~100–130 word script.',
  '3. ## Voiceover — wrap the EXACT same script text inside <voiceover>...</voiceover> tags. No markdown, no speaker labels, no stage directions. Plain spoken text only. This is what will be passed to HeyGen verbatim.',
  '4. ## Caption — caption with 3–5 hashtags.',
  '',
  'Stay strictly in Dr. Wei voice. One idea only. No anti-medicine framing. No product mention. Hook fires before any credential reference.'
].join('\n');

return [{
  json: {
    system_prompt: spec.system_prompt,
    user_brief: userBrief
  }
}];

// Extract the generated markdown + the voiceover text and log to stdout
// (visible via: docker logs -f channel-factory-n8n)
const response = $input.first().json;

if (!response.content || !Array.isArray(response.content) || !response.content[0]) {
  console.error('[Dr. Wei] Unexpected API response shape:');
  console.error(JSON.stringify(response, null, 2));
  throw new Error('Claude API response missing content[0]');
}

const markdown = response.content[0].text;
const usage = response.usage || {};

// Pull the exact voiceover text out of <voiceover>...</voiceover>.
const match = markdown.match(/<voiceover>([\s\S]*?)<\/voiceover>/i);
if (!match) {
  console.error('[Dr. Wei] Claude response is missing <voiceover>...</voiceover> tags:');
  console.error(markdown);
  throw new Error('No <voiceover> tags in generated script');
}
const voiceover = match[1].trim();

console.log('\n' + '='.repeat(60));
console.log('  DR. WEI — GENERATED SCRIPT');
console.log('  model: ' + (response.model || 'unknown'));
console.log('  tokens: ' + (usage.input_tokens || '?') + ' in / ' + (usage.output_tokens || '?') + ' out');
console.log('='.repeat(60) + '\n');
console.log(markdown);
console.log('\n' + '-'.repeat(60));
console.log('  VOICEOVER EXTRACTED (' + voiceover.length + ' chars)');
console.log('-'.repeat(60));
console.log(voiceover);
console.log('\n' + '='.repeat(60) + '\n');

return [{
  json: {
    markdown,
    voiceover,
    model: response.model,
    usage,
    generated_at: new Date().toISOString()
  }
}];

// Generate the HeyGen avatar video from the voiceover text.
// Calls POST /v2/video/generate, then polls GET /v1/video_status.get
// until status === 'completed' (or 'failed').
//
// Required env: HEYGEN_API_KEY, HEYGEN_TALKING_PHOTO_ID, HEYGEN_VOICE_ID
// Uses talking_photo character (Dr. Mei Wei) + ElevenLabs voice via HeyGen.
// HTTP: uses n8n's this.helpers.httpRequest (fetch is not available in the sandbox).

const apiKey = $env.HEYGEN_API_KEY;
const talkingPhotoId = $env.HEYGEN_TALKING_PHOTO_ID;
const voiceId = $env.HEYGEN_VOICE_ID;

if (!apiKey) throw new Error('HEYGEN_API_KEY not set in environment');
if (!talkingPhotoId) throw new Error('HEYGEN_TALKING_PHOTO_ID not set in environment');
if (!voiceId) throw new Error('HEYGEN_VOICE_ID not set in environment');

const voiceover = $input.first().json.voiceover;
if (!voiceover) throw new Error('No voiceover text in input');

const generateBody = {
  video_inputs: [
    {
      character: {
        type: 'talking_photo',
        talking_photo_id: talkingPhotoId,
        talking_photo_style: 'square',
        talking_style: 'stable',
        expression: 'default',
        scale: 1.0
      },
      voice: {
        type: 'text',
        input_text: voiceover,
        voice_id: voiceId
      },
      background: {
        type: 'color',
        value: '#f5f1e8'
      }
    }
  ],
  dimension: { width: 720, height: 1280 },
  test: false,
  caption: false
};

console.log('\n[HeyGen] Submitting video generation request...');
let genJson;
try {
  genJson = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.heygen.com/v2/video/generate',
    headers: {
      'X-Api-Key': apiKey,
      'Content-Type': 'application/json',
      'Accept': 'application/json'
    },
    body: generateBody,
    json: true
  });
} catch (err) {
  console.error('[HeyGen] Generate request failed:', err.message);
  throw err;
}

if (genJson.error) {
  console.error('[HeyGen] Generate returned error:', JSON.stringify(genJson, null, 2));
  throw new Error('HeyGen generate error: ' + (genJson.error.message || JSON.stringify(genJson.error)));
}

const videoId = genJson.data && genJson.data.video_id;
if (!videoId) {
  console.error('[HeyGen] No video_id in response:', JSON.stringify(genJson, null, 2));
  throw new Error('HeyGen generate returned no video_id');
}

console.log('[HeyGen] video_id = ' + videoId);
console.log('[HeyGen] Polling status every 15s (max 5 min)...');

const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const maxAttempts = 40; // 40 * 20s = 800s (~13 min). HeyGen routinely takes 5–8 min.
let status = 'pending';
let videoUrl = null;
let thumbnailUrl = null;
let duration = null;
let lastPayload = null;

for (let attempt = 1; attempt <= maxAttempts; attempt++) {
  await sleep(20000);
  let statusJson;
  try {
    statusJson = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.heygen.com/v1/video_status.get',
      qs: { video_id: videoId },
      headers: { 'X-Api-Key': apiKey, 'Accept': 'application/json' },
      json: true
    });
  } catch (err) {
    console.error('[HeyGen] Status poll attempt ' + attempt + ' failed: ' + err.message);
    continue;
  }
  lastPayload = statusJson;
  status = (statusJson.data && statusJson.data.status) || 'unknown';
  console.log('[HeyGen] attempt ' + attempt + '/' + maxAttempts + ' → status: ' + status);

  if (status === 'completed') {
    videoUrl = statusJson.data.video_url;
    thumbnailUrl = statusJson.data.thumbnail_url;
    duration = statusJson.data.duration;
    break;
  }
  if (status === 'failed') {
    console.error('[HeyGen] Video generation failed:', JSON.stringify(statusJson, null, 2));
    throw new Error('HeyGen video failed: ' + ((statusJson.data && statusJson.data.error && statusJson.data.error.message) || 'unknown error'));
  }
}

if (status !== 'completed') {
  console.error('[HeyGen] Timed out after 5 minutes. Last payload:');
  console.error(JSON.stringify(lastPayload, null, 2));
  throw new Error('HeyGen polling timed out (last status: ' + status + ')');
}

console.log('\n' + '='.repeat(60));
console.log('  DR. WEI — HEYGEN VIDEO READY');
console.log('='.repeat(60));
console.log('  video_id:     ' + videoId);
console.log('  duration:     ' + (duration != null ? duration : '?') + 's');
console.log('  video_url:    ' + videoUrl);
console.log('  thumbnail:    ' + thumbnailUrl);
console.log('='.repeat(60) + '\n');

return [{
  json: {
    ...$input.first().json,
    heygen: {
      video_id: videoId,
      video_url: videoUrl,
      thumbnail_url: thumbnailUrl,
      duration_seconds: duration,
      status: 'completed'
    }
  }
}];
